/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_COVERAGE_DEFINITION
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_COVERAGE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_delta3
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_COVERAGE_HK
   hashdiff    : SAT_COVERAGE_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_COVERAGE|' || (HUB_COVERAGE_BK__COVER_CODE))) as HUB_COVERAGE_HK
        , cast(null as varchar) as SELF_COVERED_INDICATOR
        , SECTION_ID as SECTION_REFERENCE
        , RATING_FLAG as RATING_PARTICIPATION_INDICATOR
        , CHECKBOX_YN as INDEPENDENTLY_SELECTABLE_INDICATOR
        , DISP_ORDER as CATALOGUE_DISPLAY_ORDER
        , 'BJAZ_STARPKG_COVER_MST' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_starpkg_cover_mst') }}
    where (nullif(trim(COVER_CODE),'')) is not null
),

resolved as (
    select
        HUB_COVERAGE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SELF_COVERED_INDICATOR end) as SELF_COVERED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SECTION_REFERENCE end) as SECTION_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then RATING_PARTICIPATION_INDICATOR end) as RATING_PARTICIPATION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then INDEPENDENTLY_SELECTABLE_INDICATOR end) as INDEPENDENTLY_SELECTABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CATALOGUE_DISPLAY_ORDER end) as CATALOGUE_DISPLAY_ORDER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_COVERAGE_HK
),

hashed as (
    select
        *,
        case when SELF_COVERED_INDICATOR is not null or SECTION_REFERENCE is not null or RATING_PARTICIPATION_INDICATOR is not null or INDEPENDENTLY_SELECTABLE_INDICATOR is not null or CATALOGUE_DISPLAY_ORDER is not null
                     then md5(upper(coalesce(cast(SELF_COVERED_INDICATOR as varchar), '') || '|' || coalesce(cast(SECTION_REFERENCE as varchar), '') || '|' || coalesce(cast(RATING_PARTICIPATION_INDICATOR as varchar), '') || '|' || coalesce(cast(INDEPENDENTLY_SELECTABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(CATALOGUE_DISPLAY_ORDER as varchar), '')))
                end as SAT_COVERAGE_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_COVERAGE_HK is not null
  and SAT_COVERAGE_DEFINITION_HASHDIFF is not null
